-- 1. Tabla Base de Productos (Neg_base)
CREATE TABLE IF NOT EXISTS public."Neg_base" (
    "Id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Codigo_provedor" TEXT,
    "Provedor" TEXT,
    "Codigo_Articulo" TEXT,
    "Descripcion_articulo" TEXT,
    "Precio" NUMERIC DEFAULT 0,
    "Cantidad" NUMERIC DEFAULT 1,
    "Unidad_de_medida" TEXT
);

-- 2. Tabla de Productos de Proveedores (Operacional)
-- Almacena el catálogo de productos y el "precio actual" que se actualizará tras cada negociación.
CREATE TABLE IF NOT EXISTS public."Neg_productos" (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    supplier_id TEXT NOT NULL, -- Relacionado con el ID/NIT del proveedor
    supplier_name TEXT,
    descripcion TEXT NOT NULL,
    precio_actual NUMERIC NOT NULL DEFAULT 0,
    cantidad_mensual NUMERIC DEFAULT 1,
    tipo TEXT DEFAULT 'Ahorro', -- 'Ahorro' o 'Avoidance'
    porcentaje_base NUMERIC DEFAULT 0,
    porcentaje_negociado NUMERIC DEFAULT 0,
    comentarios TEXT,
    base_id BIGINT,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL
);

-- 3. Tabla de Historial de Negociaciones
-- Guarda un registro cada vez que se cambia un precio.
CREATE TABLE IF NOT EXISTS public."Neg_historial_precios" (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    product_id BIGINT REFERENCES public."Neg_productos"(id),
    supplier_id TEXT,
    supplier_name TEXT,
    fecha_cambio TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL,
    precio_anterior NUMERIC NOT NULL,
    precio_nuevo NUMERIC NOT NULL,
    ahorro_generado NUMERIC,
    cantidad_mensual NUMERIC,
    tipo TEXT DEFAULT 'Ahorro',
    porcentaje_base NUMERIC DEFAULT 0,
    porcentaje_negociado NUMERIC DEFAULT 0,
    comentarios TEXT,
    usuario_id UUID, -- Opcional, si quieres registrar quién hizo el cambio
    negociacion_id TEXT -- Identificador agrupador de sesiones de negociación
);

-- Permisos (Políticas de Row Level Security para Supabase)
ALTER TABLE public."Neg_base" ENABLE ROW LEVEL SECURITY;
ALTER TABLE public."Neg_productos" ENABLE ROW LEVEL SECURITY;
ALTER TABLE public."Neg_historial_precios" ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Acceso total a base" ON public."Neg_base" FOR ALL USING (true) WITH CHECK (true);
CREATE POLICY "Acceso total a productos" ON public."Neg_productos" FOR ALL USING (true) WITH CHECK (true);
CREATE POLICY "Acceso total a historial" ON public."Neg_historial_precios" FOR ALL USING (true) WITH CHECK (true);


